//! A pydantic 2.13 (lax mode) compatible validator for the model shapes the hub uses. Messages, error `type`s, `loc`s,
//! error order and `str(ValidationError)` match pydantic exactly; they reach the API (422 `errors`, content `issues`)
//! and the UI. Golden cases: tests/golden/models.json (generated by backend/parity/gen/gen_models_golden.py).
//! Owner: CORE (LOCKED API: [`Ty`], [`Field`], [`Model`], [`validate`], [`ValidationError`]).

use std::fmt;

use regex::Regex;
use serde_json::{Map, Value};

use crate::value::PyValue;

#[derive(Debug, Clone, PartialEq)]
pub enum Loc {
    Key(String),
    Index(usize),
    /// a negative int dict key (pydantic keeps int keys as ints in `loc`; addendum A-9)
    Int(i64),
}

impl fmt::Display for Loc {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Loc::Key(k) => f.write_str(k),
            Loc::Index(i) => write!(f, "{i}"),
            Loc::Int(i) => write!(f, "{i}"),
        }
    }
}

/// pydantic-core's location item for a dict key: a str as itself, an int that fits i64 (a bool as its int) as an int,
/// anything else as its `repr()` (`2.5`, `None`, `datetime.date(2024, 1, 2)`, a big int's digits).
pub fn key_loc(k: &PyValue) -> Loc {
    match k {
        PyValue::Str(s) => Loc::Key(s.clone()),
        PyValue::Int(i) => usize::try_from(*i).map_or(Loc::Int(*i), Loc::Index),
        PyValue::Bool(b) => Loc::Index(usize::from(*b)),
        other => Loc::Key(other.repr()),
    }
}

/// The location line of `str(ValidationError)`: like [`loc_str`], but a string item containing `.` is shown in
/// backticks (pydantic-core's display).
fn display_loc(loc: &[Loc]) -> String {
    loc.iter()
        .map(|l| match l {
            Loc::Key(k) if k.contains('.') => format!("`{k}`"),
            other => other.to_string(),
        })
        .collect::<Vec<_>>()
        .join(".")
}

#[derive(Debug, Clone)]
pub struct ErrItem {
    pub loc: Vec<Loc>,
    pub msg: String,
    pub kind: String,
    pub input: PyValue,
}

/// `pydantic.ValidationError`.
#[derive(Debug, Clone)]
pub struct ValidationError {
    pub title: String,
    pub errors: Vec<ErrItem>,
}

/// pydantic truncates `input_value` reprs longer than 50 characters to 25 + "..." + 24.
fn truncated_repr(v: &PyValue) -> String {
    let r = v.repr();
    let chars: Vec<char> = r.chars().collect();
    if chars.len() > 50 {
        let head: String = chars[..25].iter().collect();
        let tail: String = chars[chars.len() - 24..].iter().collect();
        format!("{head}...{tail}")
    } else {
        r
    }
}

impl fmt::Display for ValidationError {
    /// `str(exc)`.
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let n = self.errors.len();
        write!(
            f,
            "{n} validation error{} for {}",
            if n == 1 { "" } else { "s" },
            self.title
        )?;
        for e in &self.errors {
            if !e.loc.is_empty() {
                write!(f, "\n{}", display_loc(&e.loc))?;
            }
            write!(
                f,
                "\n  {} [type={}, input_value={}, input_type={}]\n    For further information visit https://errors.pydantic.dev/2.13/v/{}",
                e.msg,
                e.kind,
                truncated_repr(&e.input),
                e.input.type_name(),
                e.kind
            )?;
        }
        Ok(())
    }
}

impl std::error::Error for ValidationError {}

/// `".".join(str(x) for x in loc)`.
pub fn loc_str(loc: &[Loc]) -> String {
    loc.iter().map(ToString::to_string).collect::<Vec<_>>().join(".")
}

impl ValidationError {
    /// `[{"loc": [...], "msg": ..., "type": ...}]` (FastAPI's handler and `errors(include_input=False, include_url=False)`
    /// minus `ctx`).
    pub fn errors_json(&self, prefix: &[Loc]) -> Value {
        Value::Array(
            self.errors
                .iter()
                .map(|e| {
                    let mut m = Map::new();
                    let loc: Vec<Value> = prefix
                        .iter()
                        .chain(e.loc.iter())
                        .map(|l| match l {
                            Loc::Key(k) => Value::String(k.clone()),
                            Loc::Index(i) => Value::from(*i),
                            Loc::Int(i) => Value::from(*i),
                        })
                        .collect();
                    m.insert("loc".into(), Value::Array(loc));
                    m.insert("msg".into(), Value::String(e.msg.clone()));
                    m.insert("type".into(), Value::String(e.kind.clone()));
                    Value::Object(m)
                })
                .collect(),
        )
    }
}

/// Literal member.
#[derive(Debug, Clone, Copy)]
pub enum Lit {
    S(&'static str),
    I(i64),
}

/// A custom validator: `Err(message)` becomes `Value error, <message>`.
pub type Check = fn(&PyValue) -> Result<(), String>;

pub enum Ty {
    Str {
        min: Option<usize>,
        max: Option<usize>,
        pattern: Option<&'static str>,
    },
    Int {
        ge: Option<i64>,
        le: Option<i64>,
    },
    Float,
    Bool,
    Any,
    Lit(&'static [Lit]),
    Opt(Box<Ty>),
    List(Box<Ty>),
    /// dict[K, V]
    Dict(Box<Ty>, Box<Ty>),
    Model(fn() -> &'static Model),
    /// `Annotated[T, AfterValidator(check)]`
    After(Box<Ty>, Check),
}

impl Ty {
    pub fn str() -> Ty {
        Ty::Str {
            min: None,
            max: None,
            pattern: None,
        }
    }
    pub fn int() -> Ty {
        Ty::Int { ge: None, le: None }
    }
    pub fn opt(t: Ty) -> Ty {
        Ty::Opt(Box::new(t))
    }
    pub fn list(t: Ty) -> Ty {
        Ty::List(Box::new(t))
    }
    pub fn dict(k: Ty, v: Ty) -> Ty {
        Ty::Dict(Box::new(k), Box::new(v))
    }
    pub fn after(t: Ty, c: Check) -> Ty {
        Ty::After(Box::new(t), c)
    }
}

pub enum Extra {
    Forbid,
    Allow,
    Ignore,
}

pub struct Field {
    pub name: &'static str,
    pub ty: Ty,
    /// `None` = required; `Some(f)` = default value factory.
    pub default: Option<fn() -> PyValue>,
    /// `@field_validator(name)` (after mode): runs on the validated value; its loc is the field.
    pub check: Option<Check>,
}

pub struct Model {
    pub name: &'static str,
    pub fields: Vec<Field>,
    pub extra: Extra,
    /// `@model_validator(mode="after")` on the validated dict; loc `()`.
    pub check: Option<Check>,
    /// Post-processing pydantic does inside a field validator that RETURNS a new value (e.g. dedupe of members).
    pub transform: Option<fn(PyValue) -> PyValue>,
}

pub fn required(name: &'static str, ty: Ty) -> Field {
    Field {
        name,
        ty,
        default: None,
        check: None,
    }
}

pub fn optional(name: &'static str, ty: Ty, default: fn() -> PyValue) -> Field {
    Field {
        name,
        ty,
        default: Some(default),
        check: None,
    }
}

fn err(loc: &[Loc], kind: &str, msg: impl Into<String>, input: &PyValue) -> ErrItem {
    ErrItem {
        loc: loc.to_vec(),
        msg: msg.into(),
        kind: kind.into(),
        input: input.clone(),
    }
}

fn plural(n: usize, word: &str) -> String {
    if n == 1 {
        format!("{n} {word}")
    } else {
        format!("{n} {word}s")
    }
}

fn lit_expected(lits: &[Lit]) -> String {
    let parts: Vec<String> = lits
        .iter()
        .map(|l| match l {
            Lit::S(s) => crate::py::text::repr(s),
            Lit::I(i) => i.to_string(),
        })
        .collect();
    match parts.len() {
        0 => String::new(),
        1 => parts[0].clone(),
        n => format!("{} or {}", parts[..n - 1].join(", "), parts[n - 1]),
    }
}

const TRUE_STR: [&str; 6] = ["1", "on", "t", "true", "y", "yes"];
const FALSE_STR: [&str; 6] = ["0", "off", "f", "false", "n", "no"];

fn parse_int_str(s: &str) -> Option<i64> {
    crate::py::text::parse_int(s)
}

/// A str int literal beyond i64 as normalised decimal text (`PyValue::BigInt`), pydantic's lax `int` from str.
fn big_int_str(s: &str) -> Option<String> {
    let t = crate::py::text::strip(s);
    let (neg, t) = match t.strip_prefix('-') {
        Some(r) => (true, r),
        None => (false, t.strip_prefix('+').unwrap_or(t)),
    };
    if t.is_empty() || t.starts_with('_') || t.ends_with('_') || t.contains("__") {
        return None;
    }
    let digits: String = t.chars().filter(|c| *c != '_').collect();
    if digits.is_empty() || !digits.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    let digits = digits.trim_start_matches('0');
    let digits = if digits.is_empty() { "0" } else { digits };
    Some(if neg && digits != "0" {
        format!("-{digits}")
    } else {
        digits.to_string()
    })
}

/// pydantic 2.13 lax `str`: a str, or bytes that decode as UTF-8 (`string_unicode` otherwise); `Err((type, msg))`.
pub fn lax_str(v: &PyValue) -> Result<String, (&'static str, &'static str)> {
    match v {
        PyValue::Str(s) => Ok(s.clone()),
        PyValue::Bytes(b) => String::from_utf8(b.clone()).map_err(|_| {
            (
                "string_unicode",
                "Input should be a valid string, unable to parse raw data as a unicode string",
            )
        }),
        _ => Err(("string_type", "Input should be a valid string")),
    }
}

/// pydantic 2.13 lax `bool` (measured against pydantic-core): bools; the ints 0/1 (any other int `bool_parsing`, an
/// int beyond i64 `bool_type`); a float equal to 0/1 (another integral float within i64 takes the int path:
/// `bool_parsing`; any other float, NaN or infinity: `bool_type`); a str or UTF-8 bytes among the yes/no words
/// (`bool_parsing` otherwise); anything else `bool_type`.
pub fn lax_bool(v: &PyValue) -> Result<bool, (&'static str, &'static str)> {
    const PARSING: (&str, &str) = (
        "bool_parsing",
        "Input should be a valid boolean, unable to interpret input",
    );
    const TYPE: (&str, &str) = ("bool_type", "Input should be a valid boolean");
    let from_str = |s: &str| {
        let l = crate::py::text::strip(s).to_lowercase();
        if TRUE_STR.contains(&l.as_str()) {
            Ok(true)
        } else if FALSE_STR.contains(&l.as_str()) {
            Ok(false)
        } else {
            Err(PARSING)
        }
    };
    match v {
        PyValue::Bool(b) => Ok(*b),
        PyValue::Int(0) => Ok(false),
        PyValue::Int(1) => Ok(true),
        PyValue::Int(_) => Err(PARSING),
        PyValue::Float(f) if *f == 0.0 => Ok(false),
        PyValue::Float(f) if *f == 1.0 => Ok(true),
        #[allow(clippy::cast_precision_loss)]
        PyValue::Float(f) if f.is_finite() && f.fract() == 0.0 && f.abs() < i64::MAX as f64 => Err(PARSING),
        PyValue::Str(s) => from_str(s),
        PyValue::Bytes(b) => std::str::from_utf8(b).map_err(|_| PARSING).and_then(from_str),
        _ => Err(TYPE),
    }
}

/// Validate `v` against `ty` at `loc`, pushing errors; returns the validated value (meaningful only without errors).
pub fn validate_ty(ty: &Ty, v: &PyValue, loc: &mut Vec<Loc>, errs: &mut Vec<ErrItem>) -> PyValue {
    match ty {
        Ty::Any => v.clone(),
        Ty::Str { min, max, pattern } => {
            let s = match lax_str(v) {
                Ok(s) => s,
                Err((kind, msg)) => {
                    errs.push(err(loc, kind, msg, v));
                    return PyValue::None;
                }
            };
            let s = s.as_str();
            let n = s.chars().count();
            if let Some(m) = min
                && n < *m
            {
                errs.push(err(
                    loc,
                    "string_too_short",
                    format!("String should have at least {}", plural(*m, "character")),
                    v,
                ));
                return PyValue::None;
            }
            if let Some(m) = max
                && n > *m
            {
                errs.push(err(
                    loc,
                    "string_too_long",
                    format!("String should have at most {}", plural(*m, "character")),
                    v,
                ));
                return PyValue::None;
            }
            if let Some(p) = pattern {
                let ok = Regex::new(p).map(|r| r.is_match(s)).unwrap_or(false);
                if !ok {
                    errs.push(err(
                        loc,
                        "string_pattern_mismatch",
                        format!("String should match pattern '{p}'"),
                        v,
                    ));
                    return PyValue::None;
                }
            }
            PyValue::Str(s.to_string())
        }
        Ty::Int { ge, le } => {
            // an int beyond i64 (Python ints are unbounded): pydantic keeps it; only its sign matters for ge/le
            #[allow(clippy::cast_precision_loss)]
            if let PyValue::Float(f) = v
                && f.is_finite()
                && f.fract() == 0.0
                && f.abs() >= i64::MAX as f64
            {
                // pydantic-core converts an integral float through i64 only
                let msg = "Unable to parse input string as an integer, exceeded maximum size";
                errs.push(err(loc, "int_parsing_size", msg, v));
                return PyValue::None;
            }
            let big = match v {
                PyValue::BigInt(d) => Some(d.clone()),
                PyValue::Str(s) if parse_int_str(s).is_none() => big_int_str(s),
                _ => None,
            };
            if let Some(d) = big {
                let neg = d.starts_with('-');
                if let Some(g) = ge
                    && neg
                {
                    let msg = format!("Input should be greater than or equal to {g}");
                    errs.push(err(loc, "greater_than_equal", msg, v));
                    return PyValue::None;
                }
                if let Some(l) = le
                    && !neg
                {
                    let msg = format!("Input should be less than or equal to {l}");
                    errs.push(err(loc, "less_than_equal", msg, v));
                    return PyValue::None;
                }
                return PyValue::BigInt(d);
            }
            let i = match v {
                PyValue::Int(i) => *i,
                PyValue::Bool(b) => i64::from(*b),
                PyValue::Float(f) => {
                    if f.fract() != 0.0 || !f.is_finite() {
                        errs.push(err(
                            loc,
                            "int_from_float",
                            "Input should be a valid integer, got a number with a fractional part",
                            v,
                        ));
                        return PyValue::None;
                    }
                    #[allow(clippy::cast_possible_truncation)]
                    let x = *f as i64;
                    x
                }
                PyValue::Str(s) => match parse_int_str(s) {
                    Some(i) => i,
                    None => {
                        errs.push(err(
                            loc,
                            "int_parsing",
                            "Input should be a valid integer, unable to parse string as an integer",
                            v,
                        ));
                        return PyValue::None;
                    }
                },
                _ => {
                    errs.push(err(loc, "int_type", "Input should be a valid integer", v));
                    return PyValue::None;
                }
            };
            if let Some(g) = ge
                && i < *g
            {
                errs.push(err(
                    loc,
                    "greater_than_equal",
                    format!("Input should be greater than or equal to {g}"),
                    v,
                ));
                return PyValue::None;
            }
            if let Some(l) = le
                && i > *l
            {
                errs.push(err(
                    loc,
                    "less_than_equal",
                    format!("Input should be less than or equal to {l}"),
                    v,
                ));
                return PyValue::None;
            }
            PyValue::Int(i)
        }
        Ty::Float => match v {
            PyValue::Float(f) => PyValue::Float(*f),
            // an int beyond i64 becomes the nearest float; beyond f64's range pydantic answers float_type
            PyValue::BigInt(d) => match d.parse::<f64>() {
                Ok(f) if f.is_finite() => PyValue::Float(f),
                _ => {
                    errs.push(err(loc, "float_type", "Input should be a valid number", v));
                    PyValue::None
                }
            },
            #[allow(clippy::cast_precision_loss)]
            PyValue::Int(i) => PyValue::Float(*i as f64),
            PyValue::Bool(b) => PyValue::Float(f64::from(u8::from(*b))),
            PyValue::Str(s) => match s.trim().parse::<f64>() {
                Ok(f) => PyValue::Float(f),
                Err(_) => {
                    errs.push(err(
                        loc,
                        "float_parsing",
                        "Input should be a valid number, unable to parse string as a number",
                        v,
                    ));
                    PyValue::None
                }
            },
            _ => {
                errs.push(err(loc, "float_type", "Input should be a valid number", v));
                PyValue::None
            }
        },
        Ty::Bool => match lax_bool(v) {
            Ok(b) => PyValue::Bool(b),
            Err((kind, msg)) => {
                errs.push(err(loc, kind, msg, v));
                PyValue::None
            }
        },
        Ty::Lit(lits) => {
            let hit = lits.iter().any(|l| match (l, v) {
                (Lit::S(s), PyValue::Str(x)) => s == x,
                (Lit::I(i), PyValue::Int(x)) => i == x,
                _ => false,
            });
            if hit {
                v.clone()
            } else {
                errs.push(err(
                    loc,
                    "literal_error",
                    format!("Input should be {}", lit_expected(lits)),
                    v,
                ));
                PyValue::None
            }
        }
        Ty::Opt(inner) => {
            if v.is_none() {
                PyValue::None
            } else {
                validate_ty(inner, v, loc, errs)
            }
        }
        Ty::List(inner) => {
            let (PyValue::List(items) | PyValue::Set(items)) = v else {
                errs.push(err(loc, "list_type", "Input should be a valid list", v));
                return PyValue::None;
            };
            let mut out = Vec::with_capacity(items.len());
            for (i, it) in items.iter().enumerate() {
                loc.push(Loc::Index(i));
                out.push(validate_ty(inner, it, loc, errs));
                loc.pop();
            }
            PyValue::List(out)
        }
        Ty::Dict(kt, vt) => {
            let Some(d) = v.as_dict() else {
                errs.push(err(loc, "dict_type", "Input should be a valid dictionary", v));
                return PyValue::None;
            };
            let mut out = Vec::with_capacity(d.len());
            for (k, val) in d {
                loc.push(key_loc(k));
                loc.push(Loc::Key("[key]".into()));
                let kk = validate_ty(kt, k, loc, errs);
                loc.pop();
                let vv = validate_ty(vt, val, loc, errs);
                loc.pop();
                out.push((kk, vv));
            }
            PyValue::Dict(out)
        }
        Ty::Model(get) => validate_model_at(get(), v, loc, errs),
        Ty::After(inner, check) => {
            let before = errs.len();
            let out = validate_ty(inner, v, loc, errs);
            if errs.len() == before
                && let Err(m) = check(&out)
            {
                errs.push(err(loc, "value_error", format!("Value error, {m}"), &out));
            }
            out
        }
    }
}

fn validate_model_at(model: &Model, v: &PyValue, loc: &mut Vec<Loc>, errs: &mut Vec<ErrItem>) -> PyValue {
    let Some(d) = v.as_dict() else {
        errs.push(err(
            loc,
            "model_type",
            format!("Input should be a valid dictionary or instance of {}", model.name),
            v,
        ));
        return PyValue::None;
    };
    let before = errs.len();
    let mut out: Vec<(PyValue, PyValue)> = Vec::new();
    for f in &model.fields {
        let given = d.iter().find(|(k, _)| k.as_str() == Some(f.name)).map(|(_, v)| v);
        loc.push(Loc::Key(f.name.into()));
        match given {
            Some(val) => {
                let fb = errs.len();
                let vv = validate_ty(&f.ty, val, loc, errs);
                if errs.len() == fb
                    && let Some(check) = f.check
                    && let Err(m) = check(&vv)
                {
                    errs.push(err(loc, "value_error", format!("Value error, {m}"), &vv));
                }
                out.push((PyValue::str(f.name), vv));
            }
            None => match f.default {
                Some(def) => out.push((PyValue::str(f.name), def())),
                None => errs.push(err(loc, "missing", "Field required", v)),
            },
        }
        loc.pop();
    }
    for (k, val) in d {
        if k.as_str().is_none() {
            // pydantic-core: a non-str key is skipped by an `ignore` model, an `invalid_key` error otherwise
            if !matches!(model.extra, Extra::Ignore) {
                loc.push(key_loc(k));
                errs.push(err(loc, "invalid_key", "Keys should be strings", k));
                loc.pop();
            }
            continue;
        }
        let known = k.as_str().is_some_and(|s| model.fields.iter().any(|f| f.name == s));
        if known {
            continue;
        }
        match model.extra {
            Extra::Forbid => {
                loc.push(Loc::Key(k.py_str()));
                errs.push(err(loc, "extra_forbidden", "Extra inputs are not permitted", val));
                loc.pop();
            }
            Extra::Allow => out.push((k.clone(), val.clone())),
            Extra::Ignore => {}
        }
    }
    let mut result = PyValue::Dict(out);
    if errs.len() == before {
        if let Some(t) = model.transform {
            result = t(result);
        }
        if let Some(check) = model.check
            && let Err(m) = check(&result)
        {
            errs.push(err(loc, "value_error", format!("Value error, {m}"), v));
        }
    }
    result
}

/// `Model.model_validate(v)`: the validated dict (declared fields in order with defaults, then allowed extras).
pub fn validate(model: &Model, v: &PyValue) -> Result<PyValue, ValidationError> {
    let mut errs = Vec::new();
    let out = validate_model_at(model, v, &mut Vec::new(), &mut errs);
    if errs.is_empty() {
        Ok(out)
    } else {
        Err(ValidationError {
            title: model.name.into(),
            errors: errs,
        })
    }
}

/// `model.model_dump(mode="json", exclude_none=...)` of a validated value, guided by the schema: with `exclude_none`,
/// None-valued fields and allowed extras of every (nested) model are dropped, but None items of lists and dict values
/// are kept, exactly as pydantic does. Allowed extras of an `Extra::Allow` model are dumped as given.
pub fn dump_json(model: &Model, v: &PyValue, exclude_none: bool) -> Value {
    dump_model(model, v, exclude_none)
}

fn dump_model(model: &Model, v: &PyValue, exclude_none: bool) -> Value {
    let Some(d) = v.as_dict() else { return v.to_json() };
    let mut m = Map::new();
    for (k, val) in d {
        let key = k.json_key();
        let field = model.fields.iter().find(|f| f.name == key);
        // exclude_none drops None-valued fields AND None-valued extras of an `extra="allow"` model
        if exclude_none && val.is_none() {
            continue;
        }
        let j = match field {
            Some(f) => dump_ty(&f.ty, val, exclude_none),
            None => val.to_json(),
        };
        m.insert(key, j);
    }
    Value::Object(m)
}

fn dump_ty(ty: &Ty, v: &PyValue, exclude_none: bool) -> Value {
    match (ty, v) {
        (Ty::Opt(inner) | Ty::After(inner, _), _) => dump_ty(inner, v, exclude_none),
        (Ty::List(inner), PyValue::List(items)) => {
            Value::Array(items.iter().map(|x| dump_ty(inner, x, exclude_none)).collect())
        }
        (Ty::Dict(_, vt), PyValue::Dict(items)) => Value::Object(
            items
                .iter()
                .map(|(k, x)| (k.json_key(), dump_ty(vt, x, exclude_none)))
                .collect(),
        ),
        (Ty::Model(get), PyValue::Dict(_)) => dump_model(get(), v, exclude_none),
        _ => v.to_json(),
    }
}
